import{Q as e,Tt as t,et as n,j as r,nt as i,xt as a}from"./chunks/framework.D7GyxgT6.js";var o=JSON.parse(`{"title":"watermark-js-plus 是什么？","description":"了解如何使用 watermark-js-plus 的框架无关 TypeScript API，为浏览器页面添加可见水印、图片水印和暗水印。","frontmatter":{"layout":"doc","description":"了解如何使用 watermark-js-plus 的框架无关 TypeScript API，为浏览器页面添加可见水印、图片水印和暗水印。"},"headers":[],"relativePath":"zh/guide/what-is-this.md","filePath":"zh/guide/what-is-this.md"}`),s={name:`zh/guide/what-is-this.md`};function c(r,o,s,c,l,u){let d=t(`el-backtop`);return a(),e(`div`,null,[i(d),o[0]||=n(`<h1 id="watermark-js-plus-是什么" tabindex="-1">watermark-js-plus 是什么？ <a class="header-anchor" href="#watermark-js-plus-是什么" aria-label="Permalink to “watermark-js-plus 是什么？”">​</a></h1><p><code>watermark-js-plus</code> 是一个轻量、基于 Canvas 的 TypeScript 浏览器水印库。它可以直接用于原生 JavaScript 和各种前端框架，无需安装框架专用适配器。</p><p>你可以用它为页面或指定容器添加可见水印、将水印直接绘制到现有图片中，或者创建低透明度暗水印并从截图或图片中将其显现。</p><h2 id="三种水印能力" tabindex="-1">三种水印能力 <a class="header-anchor" href="#三种水印能力" aria-label="Permalink to “三种水印能力”">​</a></h2><ul><li><strong>可见水印</strong> — 为整个页面或指定容器添加文本、多行文本、图片或富文本水印，支持灵活布局、样式、运行时更新及可选的 DOM 防篡改恢复。</li><li><strong>图片水印</strong> — 在浏览器中将文本或图片水印直接绘制到现有 <code>&lt;img&gt;</code> 元素。</li><li><strong>暗水印</strong> — 添加低透明度水印，并通过内置解码能力从截图或图片中进行视觉增强和显现。</li></ul><h2 id="面向前端开发" tabindex="-1">面向前端开发 <a class="header-anchor" href="#面向前端开发" aria-label="Permalink to “面向前端开发”">​</a></h2><ul><li><strong>框架无关</strong> — 使用同一套浏览器 API 接入原生 JavaScript、React、Vue、Angular、Svelte 等前端项目。</li><li><strong>TypeScript 优先</strong> — 为配置项和生命周期 API 提供完整的公共类型声明。</li><li><strong>ES 模块支持</strong> — 现代构建工具可以直接使用标准包入口；需要明确使用 ES 模块时，也可以从保留模块结构的 <code>watermark-js-plus/es</code> 入口导入。详见 <a href="/watermark-js-plus/zh/guide/extra/on-demand.html">ES 模块导入</a>。</li></ul><h2 id="浏览器兼容性" tabindex="-1">浏览器兼容性 <a class="header-anchor" href="#浏览器兼容性" aria-label="Permalink to “浏览器兼容性”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/chrome/chrome_48x48.png" alt="Chrome"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/firefox/firefox_48x48.png" alt="Firefox"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/safari/safari_48x48.png" alt="Safari"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/opera/opera_48x48.png" alt="Opera"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/main/src/edge/edge_48x48.png" alt="Edge"></th><th style="text-align:center;"><img src="https://raw.githubusercontent.com/alrra/browser-logos/master/src/archive/internet-explorer_9-11/internet-explorer_9-11_48x48.png" alt="IE"></th></tr></thead><tbody><tr><td style="text-align:center;">最新版 ✔</td><td style="text-align:center;">最新版 ✔</td><td style="text-align:center;">最新版 ✔</td><td style="text-align:center;">最新版 ✔</td><td style="text-align:center;">最新版 ✔</td><td style="text-align:center;">11（使用 <code>/ie</code>）✔</td></tr></tbody></table><p>默认包入口面向现代浏览器。如需支持 IE11，以及部分支持 IE10 和 IE9，请使用专门的旧版浏览器入口：</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Watermark } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;watermark-js-plus/ie&#39;</span></span></code></pre></div><p>具体用法及暗水印解码兼容性说明参见<a href="/watermark-js-plus/zh/guide/extra/ie.html">旧版浏览器支持</a>。</p>`,12)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};